import numpy as np

def select_next_node(current_node: int, destination_node: int, unvisited_nodes: np.ndarray, distance_matrix: np.ndarray) -> int:
    n_unvisited = len(unvisited_nodes)
    if n_unvisited == 1:
        return unvisited_nodes[0]
    # distances from current node to each unvisited node
    dist_current = distance_matrix[current_node, unvisited_nodes]
    # compute variance of distances from each candidate to all other unvisited nodes
    variances = []
    for u in unvisited_nodes:
        other = unvisited_nodes[unvisited_nodes != u]
        if len(other) > 0:
            dists = distance_matrix[u, other]
            var = np.var(dists)
        else:
            var = 0.0
        variances.append(var)
    variances = np.array(variances)
    # avoid zero variance causing zero score (use a tiny epsilon)
    epsilon = 1e-10
    score = dist_current * (variances + epsilon)
    best_idx = np.argmin(score)
    return int(unvisited_nodes[best_idx])
